    while True:
        line = sys.stdin.readline()
        if not line:
            break
        cmd = line.strip()
        if cmd == 'uci':
            send('id name FakeFish')
            send('id author Me')
            send('uciok')
        elif cmd == 'isready':
            send('readyok')
        elif cmd.startswith('quit') or cmd.startswith('stop'):
            break
        elif cmd.startswith('go'):
            # Immediately provide a big negative score for white
